// Types for the vendored Bergamot glue (bergamot-translator.js, generated by scripts/vendor-bergamot.mjs).
// Only what client/src/state/translate/engine.ts uses.

export interface BergamotVector<T> {
  push_back(value: T): void
  get(index: number): T
  size(): number
  delete(): void
}

export interface BergamotAlignedMemory {
  getByteArrayView(): Int8Array
  delete(): void
}

export interface BergamotResponse {
  getTranslatedText(): string
}

export interface BergamotModel {
  delete(): void
}

export interface BergamotService {
  translate(model: BergamotModel, input: BergamotVector<string>, options: BergamotVector<object>): BergamotVector<BergamotResponse>
  translateViaPivoting(first: BergamotModel, second: BergamotModel, input: BergamotVector<string>, options: BergamotVector<object>): BergamotVector<BergamotResponse>
  delete(): void
}

/** The Module object after the runtime is up: the settings passed in, plus the bindings. */
export interface BergamotModule {
  asm: Record<string, (...args: number[]) => number>
  AlignedMemory: new (bytes: number, alignment: number) => BergamotAlignedMemory
  AlignedMemoryList: new () => BergamotVector<BergamotAlignedMemory>
  VectorString: new () => BergamotVector<string>
  VectorResponseOptions: new () => BergamotVector<object>
  TranslationModel: new (config: string, model: BergamotAlignedMemory, shortlist: BergamotAlignedMemory, vocabs: BergamotVector<BergamotAlignedMemory>, quality: BergamotAlignedMemory | null) => BergamotModel
  BlockingService: new (options: { cacheSize: number }) => BergamotService
}

export interface BergamotSettings {
  instantiateWasm(imports: WebAssembly.Imports, accept: (instance: WebAssembly.Instance) => void): object
  onRuntimeInitialized(): void
  onAbort?(what: unknown): void
  print?(text: string): void
  printErr?(text: string): void
}

export default function loadBergamot(Module: BergamotSettings): BergamotModule
